package com.repairconnect.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="bookings") public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private CustomerProfile customer; @ManyToOne(optional=false) private ProviderProfile provider; @ManyToOne(optional=false) private ServiceItem service; @Column(nullable=false) private String problemTitle; @Column(length=2000) private String problemDescription; private String serviceAddress; private String city; private LocalDate preferredDate; private LocalTime preferredTime; private Double estimatedBudget; @Column(length=1000) private String additionalNotes; @Enumerated(EnumType.STRING) private BookingStatus status=BookingStatus.PENDING; private LocalDateTime createdAt=LocalDateTime.now(); private LocalDateTime updatedAt=LocalDateTime.now(); public Booking(){} public Long getId(){return id;} public CustomerProfile getCustomer(){return customer;} public void setCustomer(CustomerProfile v){customer=v;} public ProviderProfile getProvider(){return provider;} public void setProvider(ProviderProfile v){provider=v;} public ServiceItem getService(){return service;} public void setService(ServiceItem v){service=v;} public String getProblemTitle(){return problemTitle;} public void setProblemTitle(String v){problemTitle=v;} public String getProblemDescription(){return problemDescription;} public void setProblemDescription(String v){problemDescription=v;} public String getServiceAddress(){return serviceAddress;} public void setServiceAddress(String v){serviceAddress=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public LocalDate getPreferredDate(){return preferredDate;} public void setPreferredDate(LocalDate v){preferredDate=v;} public LocalTime getPreferredTime(){return preferredTime;} public void setPreferredTime(LocalTime v){preferredTime=v;} public Double getEstimatedBudget(){return estimatedBudget;} public void setEstimatedBudget(Double v){estimatedBudget=v;} public String getAdditionalNotes(){return additionalNotes;} public void setAdditionalNotes(String v){additionalNotes=v;} public BookingStatus getStatus(){return status;} public void setStatus(BookingStatus v){status=v;updatedAt=LocalDateTime.now();} public LocalDateTime getCreatedAt(){return createdAt;} }